def page(title, description, body, color=None):
    accent=f' style="--project-bg:{color}"' if color else ''
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{escape(description,quote=True)}"><meta name="theme-color" content="#f7f6f2"><title>{escape(title)} · Labhanshu Vyas</title><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="styles.css"><script src="script.js" defer></script></head>
<body{accent}><a class="skip-link" href="#main">Skip to content</a>{header()}{body}{footer()}</body></html>'''

