def viewer():
    return '''<dialog class="report-dialog" id="reportViewer" aria-labelledby="viewerTitle"><div class="viewer-toolbar"><span class="viewer-title" id="viewerTitle">Visual product report</span><div class="viewer-controls"><button type="button" data-zoom="out" aria-label="Zoom out">−</button><output aria-label="Zoom level" aria-live="polite">100%</output><button type="button" data-zoom="in" aria-label="Zoom in">+</button><button type="button" data-zoom="fit">Fit</button><button type="button" data-zoom="actual">100%</button><button type="button" data-close-viewer aria-label="Close report">Close ×</button></div></div><p class="viewer-status" role="status">Loading the full-resolution report…</p><div class="viewer-viewport" aria-label="Scrollable report"><div class="viewer-canvas"><img id="viewerImage" alt="Visual product report" hidden></div></div><p class="viewer-help">Use + and − to zoom, then scroll to read. Press Escape to close.</p></dialog>'''

def section(id,title,content,label=None):
    lead=f'<p class="reading-label">{label}</p>' if label else ''
    return f'<section class="case-section" id="{id}">{lead}<h2>{title}</h2>{content}</section>'

def case_page(p,next_p):
    steps=''.join(f'<div class="process-step"><b>0{i+1}</b><h3>{t}</h3><p>{d}</p></div>' for i,(t,d) in enumerate(p['flow']))
    measures=''.join(f'<div><dt>{t}</dt><dd>{d}</dd></div>' for t,d in p['measures'])
    sections=section('problem','Start with the decision.',f'<p>{p["problem"]}</p><div class="case-note"><strong>Working hypothesis</strong><br>{p["hypothesis"]}</div>','01 / PROBLEM & HYPOTHESIS')
    sections+=section('scope','A smaller first version.',f'<div class="decision-grid"><div class="decision-item"><h3>Start here</h3><p>{p["start"]}</p></div><div class="decision-item"><h3>Leave for later</h3><p>{p["later"]}</p></div></div><div class="process" aria-label="Proposed user journey">{steps}</div>','02 / PROPOSED SCOPE')
    sections+=section('tradeoff','Make the trade-off explicit.',f'<p>{p["tradeoff"]}</p>','03 / PRODUCT JUDGMENT')
    sections+=section('validation','Test usefulness before scale.',f'<p>{p["validation"]}</p><dl class="measure-list">{measures}</dl>','04 / PROPOSED VALIDATION')
    sections+=section('unknown','The assumption to challenge.',f'<p>{p["risk"]}</p>','05 / HARDEST UNKNOWN')
    sections+=section('next','What would change the plan?',f'<p>{p["learning"]}</p><p class="case-note">This is an independent product exploration. Interfaces are illustrative, and the tests described here are proposed. The report’s benefits and roadmap are aspirations, not measured outcomes or commitments from the named companies.</p>','06 / NEXT DECISION')
    body=f'''<main id="main"><section class="case-top"><div class="container"><a class="back-link" href="index.html#work">← Back to selected work</a><div class="case-hero"><p class="eyebrow">{p['name']} / Independent product concept</p><h1>{p['title']}</h1><p class="case-lead">{p['short']}</p><div class="case-meta"><div><span>Project type</span>Independent exploration</div><div><span>Focus</span>{p['focus']}</div><div><span>Status</span>Concept · Not launched</div></div></div></div></section><section class="case-visual"><div class="container report-teaser"><img src="assets/{p['slug']}-report-thumb.webp" width="1484" height="1060" alt="{p['name']} visual report overview"><div><p class="eyebrow">The concept at a glance</p><h2>{p['question']}</h2><p>The visual report presents the broader idea. The thinking below narrows it to an initial scope, a trade-off and a proposed test.</p><button class="button primary report-open" type="button" data-report="assets/{p['slug']}-report-full.webp" data-title="{escape(p['name'],quote=True)} visual product report">Open full report <span aria-hidden="true">⤢</span></button><noscript><p><a class="inline-link" href="assets/{p['slug']}-report-full.webp">View the full report image</a></p></noscript></div></div></section><div class="container case-body"><nav class="case-index" aria-label="Case study sections"><p class="eyebrow">Inside the thinking</p><a href="#problem">01 · Problem</a><a href="#scope">02 · First scope</a><a href="#tradeoff">03 · Trade-off</a><a href="#validation">04 · Validation</a><a href="#unknown">05 · Unknown</a><a href="#next">06 · Next decision</a></nav><div>{sections}</div></div><section class="case-next"><div class="container"><div><p class="eyebrow">Next exploration</p><h3>{next_p['name']}</h3></div><a class="button" href="{next_p['slug']}.html">Explore the case study <span aria-hidden="true">↗</span></a></div></section></main>{viewer()}'''
    (ROOT/(p['slug']+'.html')).write_text(page(p['name']+' — '+p['title'],p['short'],body,p['color']),encoding='utf-8')

