    body=f'''<main id="main"><section class="case-top"><div class="container"><a class="back-link" href="index.html#work">← Back to selected work</a><div class="case-hero"><p class="eyebrow">M.S. Corporation / Client work</p><h1>Billing and inventory,<br>from requirements<br>to implementation.</h1><p class="case-lead">A contribution summary spanning client requirements, software delivery and operational reporting.</p><div class="case-meta"><div><span>Role</span>Product Owner &amp; Lead Developer</div><div><span>Engagement</span>Freelance</div><div><span>Tools</span>SQL · Power BI · Software development</div></div></div></div></section><section class="container feature-project"><div><p class="eyebrow">Scope of contribution</p><h3>Understand the business.<br>Make it buildable.</h3><p>Requirements, implementation and reporting connected within one client engagement.</p></div>{scope_visual()}</section><div class="container case-body"><nav class="case-index" aria-label="Case study sections"><p class="eyebrow">Inside the work</p><a href="#context">01 · Context</a><a href="#contribution">02 · Contribution</a><a href="#connection">03 · Perspective</a><a href="#boundaries">04 · Scope</a></nav><div>{content}</div></div><section class="case-next"><div class="container"><div><p class="eyebrow">Independent product exploration</p><h3>Google Maps</h3></div><a class="button" href="google-maps.html">Explore the concept <span aria-hidden="true">↗</span></a></div></section></main>'''
